-- ============================================================
-- Converted from: source/schema/sales_db_schema.sql
-- Conversion date: 2026-09-10
-- Converter: sql-conversion skill v2
-- Target: Aurora PostgreSQL 17 (PostgreSQL 15+ compatible)
-- Notes:
--   SalesDB + InventoryDB consolidated into one database, schema public
--   [dbo].[PascalCase] → public.snake_case; every column renamed 1:1
--     (CustomerId → customer_id, SKU → sku) — keys are NEVER renamed to "id"
--   INT IDENTITY(1,1) → INTEGER GENERATED BY DEFAULT AS IDENTITY
--     (BY DEFAULT so the data load can insert existing keys — the
--      IDENTITY_INSERT equivalent. Explicit values do not advance the
--      sequence, so resync every identity after the load:
--      SELECT setval(pg_get_serial_sequence('public.t', 'col'),
--                    COALESCE(MAX(col), 0) + 1, false) FROM public.t;)
--   MONEY → NUMERIC(19,4); DECIMAL(p,s) → NUMERIC(p,s); BIT → BOOLEAN
--   NVARCHAR(n) → VARCHAR(n); NVARCHAR(4000) kept as VARCHAR(4000)
--   DATETIME → TIMESTAMP(3); DATETIME2 → TIMESTAMP; UNIQUEIDENTIFIER → UUID
--   DEFAULT SYSDATETIME() → DEFAULT clock_timestamp()::TIMESTAMP (wall-clock,
--     no time zone; LOCALTIMESTAMP would freeze at transaction start)
--   DEFAULT 1 on BIT → DEFAULT TRUE
--   Constraint names PK_/UQ_/FK_/DF_ → lower snake_case; DF_ names dropped
--     (PostgreSQL defaults are not named objects)
--   Filtered unique index (WHERE ExternalId IS NOT NULL) → plain UNIQUE:
--     PostgreSQL UNIQUE already allows many NULLs
--   CLUSTERED / NONCLUSTERED keywords dropped (PG has no clustered indexes)
--   INCLUDE (...) columns kept (PG 11+)
-- ============================================================

-- ------------------------------------------------------------
-- Reference data
-- ------------------------------------------------------------
CREATE TABLE public.categories (
    category_id    INTEGER GENERATED BY DEFAULT AS IDENTITY
                   CONSTRAINT pk_categories PRIMARY KEY,
    category_name  VARCHAR(100) NOT NULL
                   CONSTRAINT uq_categories_category_name UNIQUE
);

CREATE TABLE public.warehouses (
    warehouse_id    INTEGER GENERATED BY DEFAULT AS IDENTITY
                    CONSTRAINT pk_warehouses PRIMARY KEY,
    warehouse_name  VARCHAR(100) NOT NULL
);

-- ------------------------------------------------------------
-- Customers
-- ------------------------------------------------------------
CREATE TABLE public.customers (
    customer_id  INTEGER GENERATED BY DEFAULT AS IDENTITY
                 CONSTRAINT pk_customers PRIMARY KEY,
    -- Filtered unique index in SQL Server → plain UNIQUE (multiple NULLs allowed)
    external_id  UUID
                 CONSTRAINT ux_customers_external_id UNIQUE,
    first_name   VARCHAR(100) NOT NULL,
    last_name    VARCHAR(100) NOT NULL,
    email        VARCHAR(255) NOT NULL
                 CONSTRAINT uq_customers_email UNIQUE,
    phone        VARCHAR(20),
    birth_date   DATE,
    referred_by  INTEGER
                 CONSTRAINT fk_customers_referred_by REFERENCES public.customers (customer_id),
    created_at   TIMESTAMP NOT NULL DEFAULT clock_timestamp()::TIMESTAMP,
    updated_at   TIMESTAMP
);

-- ------------------------------------------------------------
-- Products & inventory
-- ------------------------------------------------------------
CREATE TABLE public.products (
    product_id            INTEGER GENERATED BY DEFAULT AS IDENTITY
                          CONSTRAINT pk_products PRIMARY KEY,
    sku                   VARCHAR(50)   NOT NULL
                          CONSTRAINT uq_products_sku UNIQUE,
    product_name          VARCHAR(200)  NOT NULL,
    category              VARCHAR(100),
    category_id           INTEGER
                          CONSTRAINT fk_products_categories REFERENCES public.categories (category_id),
    price                 NUMERIC(19,4) NOT NULL DEFAULT 0,
    weight_lbs            NUMERIC(10,3),
    is_active             BOOLEAN       NOT NULL DEFAULT TRUE,
    reorder_point         INTEGER,
    reorder_quantity      INTEGER       NOT NULL DEFAULT 50,
    default_warehouse_id  INTEGER
                          CONSTRAINT fk_products_warehouses REFERENCES public.warehouses (warehouse_id),
    created_at            TIMESTAMP     NOT NULL DEFAULT clock_timestamp()::TIMESTAMP,
    updated_at            TIMESTAMP
);

CREATE TABLE public.inventory (
    product_id        INTEGER NOT NULL
                      CONSTRAINT fk_inventory_products REFERENCES public.products (product_id),
    warehouse_id      INTEGER NOT NULL
                      CONSTRAINT fk_inventory_warehouses REFERENCES public.warehouses (warehouse_id),
    quantity_on_hand  INTEGER NOT NULL DEFAULT 0,
    last_updated      TIMESTAMP,
    last_restocked    TIMESTAMP(3),
    CONSTRAINT pk_inventory PRIMARY KEY (product_id, warehouse_id)
);

CREATE TABLE public.inventory_audit (
    audit_id      INTEGER GENERATED BY DEFAULT AS IDENTITY
                  CONSTRAINT pk_inventory_audit PRIMARY KEY,
    product_id    INTEGER      NOT NULL,
    warehouse_id  INTEGER      NOT NULL,
    previous_qty  INTEGER      NOT NULL,
    adjustment    INTEGER      NOT NULL,
    new_qty       INTEGER      NOT NULL,
    reason        VARCHAR(200),
    adjusted_by   VARCHAR(100) NOT NULL,
    adjusted_at   TIMESTAMP    NOT NULL
);

CREATE TABLE public.purchase_orders (
    purchase_order_id  INTEGER GENERATED BY DEFAULT AS IDENTITY
                       CONSTRAINT pk_purchase_orders PRIMARY KEY,
    product_id         INTEGER      NOT NULL
                       CONSTRAINT fk_purchase_orders_products REFERENCES public.products (product_id),
    warehouse_id       INTEGER      NOT NULL
                       CONSTRAINT fk_purchase_orders_warehouses REFERENCES public.warehouses (warehouse_id),
    quantity           INTEGER      NOT NULL,
    status             VARCHAR(20)  NOT NULL,
    created_by         VARCHAR(100) NOT NULL,
    created_at         TIMESTAMP(3) NOT NULL
);

CREATE TABLE public.product_staging (
    staging_id      INTEGER GENERATED BY DEFAULT AS IDENTITY
                    CONSTRAINT pk_product_staging PRIMARY KEY,
    product_id      INTEGER,
    sku             VARCHAR(50)   NOT NULL,
    product_name    VARCHAR(200)  NOT NULL,
    price           NUMERIC(19,4) NOT NULL,
    category_id     INTEGER,
    is_active       BOOLEAN       NOT NULL DEFAULT TRUE,
    effective_date  DATE          NOT NULL,
    expires_date    DATE
);

CREATE TABLE public.price_audit (
    price_audit_id  INTEGER GENERATED BY DEFAULT AS IDENTITY
                    CONSTRAINT pk_price_audit PRIMARY KEY,
    product_id      INTEGER       NOT NULL,
    old_price       NUMERIC(19,4) NOT NULL,
    new_price       NUMERIC(19,4) NOT NULL,
    changed_at      TIMESTAMP(3)  NOT NULL
);

CREATE TABLE public.stock_transfers (
    transfer_id        INTEGER GENERATED BY DEFAULT AS IDENTITY
                       CONSTRAINT pk_stock_transfers PRIMARY KEY,
    from_warehouse_id  INTEGER      NOT NULL,
    to_warehouse_id    INTEGER      NOT NULL,
    product_id         INTEGER      NOT NULL,
    quantity           INTEGER      NOT NULL,
    transferred_by     VARCHAR(100) NOT NULL,
    transferred_at     TIMESTAMP    NOT NULL
);

-- ------------------------------------------------------------
-- Sales
-- ------------------------------------------------------------
CREATE TABLE public.coupons (
    coupon_id     INTEGER GENERATED BY DEFAULT AS IDENTITY
                  CONSTRAINT pk_coupons PRIMARY KEY,
    code          VARCHAR(50)  NOT NULL
                  CONSTRAINT uq_coupons_code UNIQUE,
    discount_pct  NUMERIC(5,2) NOT NULL,
    is_active     BOOLEAN      NOT NULL DEFAULT TRUE,
    expires_at    TIMESTAMP    NOT NULL,
    use_count     INTEGER      NOT NULL DEFAULT 0
);

CREATE TABLE public.invoices (
    invoice_id    INTEGER GENERATED BY DEFAULT AS IDENTITY
                  CONSTRAINT pk_invoices PRIMARY KEY,
    customer_id   INTEGER       NOT NULL
                  CONSTRAINT fk_invoices_customers REFERENCES public.customers (customer_id),
    period_start  DATE          NOT NULL,
    total_amount  NUMERIC(19,4) NOT NULL,
    created_at    TIMESTAMP     NOT NULL
);

CREATE TABLE public.orders (
    order_id           INTEGER GENERATED BY DEFAULT AS IDENTITY
                       CONSTRAINT pk_orders PRIMARY KEY,
    customer_id        INTEGER       NOT NULL
                       CONSTRAINT fk_orders_customers REFERENCES public.customers (customer_id),
    created_at         TIMESTAMP     NOT NULL DEFAULT clock_timestamp()::TIMESTAMP,
    total_amount       NUMERIC(19,4) NOT NULL,
    discount_pct       NUMERIC(5,2)  NOT NULL DEFAULT 0,
    notes              VARCHAR(500),
    status             VARCHAR(50)   NOT NULL DEFAULT 'Pending',
    requires_approval  BOOLEAN       NOT NULL DEFAULT FALSE,
    invoice_id         INTEGER
                       CONSTRAINT fk_orders_invoices REFERENCES public.invoices (invoice_id),
    updated_at         TIMESTAMP,
    processed_at       TIMESTAMP
);

CREATE INDEX ix_orders_customer_id_status
    ON public.orders (customer_id, status)
    INCLUDE (total_amount, created_at);

CREATE INDEX ix_orders_created_at
    ON public.orders (created_at DESC);

CREATE TABLE public.order_lines (
    line_id     INTEGER GENERATED BY DEFAULT AS IDENTITY
                CONSTRAINT pk_order_lines PRIMARY KEY,
    order_id    INTEGER       NOT NULL
                CONSTRAINT fk_order_lines_orders REFERENCES public.orders (order_id),
    product_id  INTEGER       NOT NULL
                CONSTRAINT fk_order_lines_products REFERENCES public.products (product_id),
    quantity    SMALLINT      NOT NULL,
    unit_price  NUMERIC(19,4) NOT NULL,
    line_total  NUMERIC(19,4)
);

CREATE TABLE public.refunds (
    refund_id     INTEGER GENERATED BY DEFAULT AS IDENTITY
                  CONSTRAINT pk_refunds PRIMARY KEY,
    order_id      INTEGER       NOT NULL
                  CONSTRAINT fk_refunds_orders REFERENCES public.orders (order_id),
    amount        NUMERIC(19,4) NOT NULL,
    reason        VARCHAR(500),
    processed_by  VARCHAR(100)  NOT NULL,
    processed_at  TIMESTAMP(3)  NOT NULL,
    status        VARCHAR(20)   NOT NULL
);

CREATE TABLE public.processing_errors (
    error_id       INTEGER GENERATED BY DEFAULT AS IDENTITY
                   CONSTRAINT pk_processing_errors PRIMARY KEY,
    order_id       INTEGER,
    error_message  VARCHAR(4000),
    occurred_at    TIMESTAMP(3) NOT NULL
);

-- ------------------------------------------------------------
-- HR
-- ------------------------------------------------------------
CREATE TABLE public.employees (
    employee_id    INTEGER GENERATED BY DEFAULT AS IDENTITY
                   CONSTRAINT pk_employees PRIMARY KEY,
    manager_id     INTEGER
                   CONSTRAINT fk_employees_manager REFERENCES public.employees (employee_id),
    employee_name  VARCHAR(200) NOT NULL,
    title          VARCHAR(100)
);
